package com.vit.sales.ui;
import com.vit.sales.db.DatabaseManager;import com.vit.sales.security.UserDao;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;
public final class UserManagementPanel extends JPanel{private final DatabaseManager db;private final UserDao dao;private final JTable table=new JTable();public UserManagementPanel(DatabaseManager db){this.db=db;dao=new UserDao(db);setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton refresh=new JButton("Refresh users"),add=new JButton("Create user"),reset=new JButton("Reset password"),toggle=new JButton("Activate/deactivate selected");refresh.addActionListener(e->load());add.addActionListener(e->create());reset.addActionListener(e->resetPassword());toggle.addActionListener(e->toggle());top.add(add);top.add(reset);top.add(toggle);top.add(refresh);add(top,BorderLayout.NORTH);table.setAutoCreateRowSorter(true);add(new JScrollPane(table),BorderLayout.CENTER);load();}
private void load(){String sql="SELECT user_id,username,`role`,is_active,failed_attempts,locked_until,last_login,created_at FROM Users ORDER BY user_id";try(Connection c=db.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){DefaultTableModel m=new DefaultTableModel();ResultSetMetaData d=r.getMetaData();for(int i=1;i<=d.getColumnCount();i++)m.addColumn(d.getColumnLabel(i));while(r.next()){Object[] a=new Object[d.getColumnCount()];for(int i=1;i<=a.length;i++)a[i-1]=r.getObject(i);m.addRow(a);}table.setModel(m);}catch(SQLException e){error(e);}}
private void create(){JTextField name=new JTextField();JPasswordField pass=new JPasswordField();JComboBox<String> role=new JComboBox<>(new String[]{"STAFF","ADMIN"});JPanel p=new JPanel(new GridLayout(0,2,6,6));p.add(new JLabel("Username"));p.add(name);p.add(new JLabel("Temporary password (10+ chars)"));p.add(pass);p.add(new JLabel("Role"));p.add(role);if(JOptionPane.showConfirmDialog(this,p,"Create user",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;char[] pw=((JPasswordField)pass).getPassword();try{String u=name.getText().trim();if(u.length()<3)throw new IllegalArgumentException("Username must be at least 3 characters.");dao.createUser(u,pw,(String)role.getSelectedItem());JOptionPane.showMessageDialog(this,"User created. Share the temporary password securely and ask them to change it outside this prototype workflow.");load();}catch(Exception e){error(e);}finally{java.util.Arrays.fill(pw,'\0');}}

private void resetPassword(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a user first.");return;}int model=table.convertRowIndexToModel(row);int id=((Number)table.getModel().getValueAt(model,0)).intValue();JPasswordField field=new JPasswordField();if(JOptionPane.showConfirmDialog(this,field,"Enter new temporary password (10+ characters)",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;char[] pw=field.getPassword();try{com.vit.sales.security.PasswordHasher.Hash h=com.vit.sales.security.PasswordHasher.hash(pw);try(Connection c=db.getConnection();PreparedStatement ps=c.prepareStatement("UPDATE Users SET password_hash=?,password_salt=?,iterations=?,failed_attempts=0,locked_until=NULL WHERE user_id=?")){ps.setString(1,h.encodedHash());ps.setString(2,h.encodedSalt());ps.setInt(3,h.iterations());ps.setInt(4,id);if(ps.executeUpdate()!=1)throw new SQLException("User no longer exists.");}JOptionPane.showMessageDialog(this,"Password reset. Communicate the temporary password privately.");load();}catch(Exception e){error(e);}finally{java.util.Arrays.fill(pw,'\0');}}
private void toggle(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a user first.");return;}int model=table.convertRowIndexToModel(row);int id=((Number)table.getModel().getValueAt(model,0)).intValue();boolean active=Boolean.parseBoolean(String.valueOf(table.getModel().getValueAt(model,3)));if(JOptionPane.showConfirmDialog(this,(active?"Deactivate":"Activate")+" selected account?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=db.getConnection();PreparedStatement ps=c.prepareStatement("UPDATE Users SET is_active=? WHERE user_id=?")){ps.setBoolean(1,!active);ps.setInt(2,id);ps.executeUpdate();load();}catch(SQLException e){error(e);}}
private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"User management failed",JOptionPane.ERROR_MESSAGE);}}
